const sections = await (await fetch('./questions.json?v=split-evaluation-20261115')).json();
const state={affine:{step:0,point:0,shear:.7},ambiguity:{x:1,z:4,f:1,lock:false,baseX:1,baseZ:4},twoview:{baseline:1,noise:0,depth:4},sfm:{points:null,cam3:2.4,selected:0,include3:true,bad:false,showReference:false,steps:0,status:'Initial estimate. Fit the reconstruction to reduce image residuals.'},prior:{mean:1.5,sigma:.35,actual:2.75,second:false,usePrior:true},shortcut:{wg:0,wc:0,extra:false,fitted:false,fitExtra:null},representations:{mode:'depth',query:0,depth:0,angle:0},evaluation:{mode:'scale',align:false,focal:1}};
let current=sections[0];
const nav=document.querySelector('#nav'), workspace=document.querySelector('#workspace'), questions=document.querySelector('#questions');
const groups=[
  {id:'evidence',title:'One image and more evidence',stages:['ambiguity','learning']},
  {id:'fitting',title:'Fit a scene',stages:['sfm']},
  {id:'evaluation',title:'Representations and evaluation',stages:['representations','evaluation']}
];
const stageNames={ambiguity:'1. Image ambiguity',learning:'2. Prior and second view',sfm:'3. Reprojection fit',representations:'4. Represent the scene',evaluation:'5. Evaluate the output'};
const slides={ambiguity:'Lecture 09 · PDF pp. 2, 20',learning:'Lecture 09 · PDF pp. 20-21, 24-25',twoview:'Lecture 08 · PDF pp. 5-7; Lecture 09 · p. 21',sfm:'Lecture 08 · PDF pp. 38-49, 65-69, 89',representations:'Lecture 09 · PDF pp. 29-32, 42-46',evaluation:'Lecture 09 · PDF pp. 32, 36-40, 48'};
function groupFor(id){return groups.find(g=>g.stages.includes(id))}
function selectStage(id){current=sections.find(s=>s.id===id);history.replaceState(null,'','#'+id);render();workspace.focus({preventScroll:true});workspace.scrollIntoView({behavior:'smooth',block:'start'})}
function updateNav(){const g=groupFor(current.id);nav.innerHTML=groups.map((item,i)=>`<button type="button" data-group="${item.id}" class="${item===g?'active':''}" aria-current="${item===g?'step':'false'}"><span>0${i+1}</span><b>${item.title}</b></button>`).join('');nav.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectStage(groups.find(x=>x.id===b.dataset.group).stages[0])))}
function stageNav(){const g=groupFor(current.id);if(g.stages.length<2)return '';return `<div class="stage-nav" aria-label="Experiments in this section">${g.stages.map(id=>`<button type="button" data-stage="${id}" class="${id===current.id?'active':''}" aria-current="${id===current.id?'step':'false'}">${stageNames[id]}</button>`).join('')}</div>${g.id==='evidence'?'<p class="shared-scene" id="shared-scene"></p>':''}`}
function nextStage(){const ids=groups.flatMap(g=>g.stages),i=ids.indexOf(current.id),id=ids[i+1];return id?`<div class="next-stage"><button type="button" data-stage="${id}">Continue: ${stageNames[id]} →</button></div>`:''}
function syncShared(){const s=state.ambiguity;set('shared-scene',`Shared scene: object height H = ${fmt(2*s.x,2)} m, distance Z = ${fmt(s.z,2)} m, focal length f = ${fmt(s.f,2)}. Its image height is h = ${fmt(2*s.f*s.x/s.z,3)}.`)}
const fmt=(n,p=2)=>Number.isFinite(n)?n.toFixed(p):'undefined';
const range=(id,label,value,min,max,step,unit='')=>`<label class="control"><span>${label}<output id="${id}-value">${fmt(value,step<.1?2:1)}${unit}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"></label>`;
const checkbox=(id,label,checked)=>`<label class="check"><input type="checkbox" id="${id}" ${checked?'checked':''}>${label}</label>`;
const metric=(label,id,detail)=>`<div class="metric"><span>${label}</span><strong id="${id}">-</strong><small>${detail}</small></div>`;
const svg=(id,label)=>`<svg id="${id}" class="plot" viewBox="0 0 800 280" role="img" aria-label="${label}"></svg>`;
const line=(x1,y1,x2,y2,color='#5e819c',width=2,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
const dot=(x,y,color='#258db5',r=6)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const label=(x,y,t,color='#5d7890',size=13)=>`<text x="${x}" y="${y}" fill="${color}" font-family="Arial" font-size="${size}">${t}</text>`;
const set=(id,s)=>{const e=document.getElementById(id);if(e)e.innerHTML=s};
const out=(id,v,p=2)=>set(id,typeof v==='number'?fmt(v,p):v);
function bindRange(id,callback){document.getElementById(id).addEventListener('input',e=>callback(Number(e.target.value)))}
function sectionShell(s,controls,visual,aside,extra=''){return `<div class="workspace">${stageNav()}<div class="section-head"><div><p class="eyebrow">0${s.number} / ${s.title.toUpperCase()}</p><h2>${s.title}.</h2><p>${s.intro}</p></div><aside class="note"><strong>LEARNING OBJECTIVE</strong>${s.objective}<br><br>${slides[s.id]}</aside></div><div class="lab"><aside class="controls"><h3>${controls.title}</h3>${controls.body}</aside><div class="viz">${visual}</div></div>${extra}<div class="experiment"><b>TRY THE EXPERIMENT</b><ol>${s.instructions.map(t=>`<li>${t}</li>`).join('')}</ol></div><p class="hint">${aside}</p>${nextStage()}</div>`}
function panel(title,id,description){return `<div class="panel"><div class="visual-title"><h3>${title}</h3><small>${description}</small></div>${svg(id,title)}</div>`}
function renderQuestions(){questions.innerHTML=`<p class="eyebrow">THINK IT THROUGH / 0${current.number}</p><h2>Worked questions</h2><p>Predict and explain before opening the worked answer.</p><div class="qgrid">${current.questions.map((q,i)=>`<article class="qcard"><h3>${current.number}.${i+1}</h3><p>${q.scenario}</p><ol type="a"><li>${q.a}</li><li>${q.b}</li></ol><details><summary>Show worked answer</summary><p><b>(a)</b> ${q.answer_a}</p><p><b>(b)</b> ${q.answer_b}</p></details></article>`).join('')}</div>`}
function ambiguity(){const s=state.ambiguity;const c={title:'Camera and point',body:range('ax','Object half-height X',s.x,.25,2,.05)+range('az','Depth Z',s.z,1,9,.01)+range('af','Focal length f',s.f,.5,2,.1)+checkbox('alock','Lock X and Z to the same scale',s.lock)+`<p class="hint">A vertical object in a 2D cross-section. In 3D, scale X, Y and Z together.</p>`};const v=panel('Camera geometry','aplot','SIDE VIEW · NOT TO SCALE')+`<div class="metrics">${metric('Image coordinate','aimage','x = fX / Z')}${metric('Scale factor','ascale','relative to lock point')}${metric('Camera depth','adepth','Z')}</div><div class="explainer">Projection discards distance along a ray. A learned prior may favour a scene but does not remove the geometric ambiguity.</div>`;workspace.innerHTML=sectionShell(current,c,v,'Values are dimensionless, and the image is shown as a virtual plane in front of the camera.');
const draw=()=>{const vs=Math.min(40,110/Math.max(s.x,s.f*s.x/s.z)),px=120+s.z*51,py=140-s.x*vs,plane=120+s.f*51,iy=140-(s.f*s.x/s.z)*vs;set('aplot',`${line(30,140,760,140,'#b5c9d8',1)}${line(120,140,px,py,'#2c96c0',2)}${line(120,140,px,280-py,'#2c96c0',2)}${line(px,py,px,280-py,'#258db5',7)}${line(plane,20,plane,260,'#c5955f',2,'5 4')}${line(plane,iy,plane,280-iy,'#c47b34',5)}${dot(120,140,'#263f56',8)}${dot(px,py,'#258db5',6)}${dot(plane,iy,'#c47b34',5)}${label(80,170,'CAMERA')}${label(plane+6,35,'IMAGE PLANE','#a96b31')}${label(px+12,py-12,'OBJECT (X, Z)')}${label(plane+8,iy-10,'x', '#ac682d')}${label(22,24,'The object and its image are vertical segments')}`);out('aimage',s.f*s.x/s.z,3);out('ascale',s.lock?s.z/s.baseZ:1,2);out('adepth',s.z);['ax','az','af'].forEach((id,i)=>out(id+'-value',[s.x,s.z,s.f][i],id==='af'?1:2));syncShared()};
bindRange('ax',v=>{s.x=s.lock?Math.max(Math.max(.25,s.baseX/s.baseZ),Math.min(Math.min(2,9*s.baseX/s.baseZ),v)):v;if(s.lock){s.z=s.baseZ*s.x/s.baseX;document.querySelector('#az').value=s.z;document.querySelector('#ax').value=s.x}draw()});bindRange('az',v=>{s.z=s.lock?Math.max(Math.max(1,.25*s.baseZ/s.baseX),Math.min(Math.min(9,2*s.baseZ/s.baseX),v)):v;if(s.lock){s.x=s.baseX*s.z/s.baseZ;document.querySelector('#ax').value=s.x;document.querySelector('#az').value=s.z}draw()});bindRange('af',v=>{s.f=v;draw()});document.querySelector('#alock').onchange=e=>{s.lock=e.target.checked;s.baseX=s.x;s.baseZ=s.z;draw()};draw()}
function sfm(){
  const s=state.sfm, focal=1, baseline=1;
  const truth=[{x:-.65,y:.42,z:3.2},{x:-.1,y:-.55,z:4.2},{x:.65,y:.38,z:4.8},{x:1.15,y:-.35,z:3.7}], colours=['#248db6','#b96d3c','#8b6aa5','#3b9174'],names=['A','B','C','D'];
  const reset=()=>{s.points=truth.map((p,i)=>({x:p.x+[.23,-.18,.24,-.21][i],y:p.y+[.11,-.10,.09,-.08][i],z:p.z*[.75,1.22,.8,1.2][i]}));s.cam3=2.4;s.steps=0;s.status='Initial estimate. Fit the reconstruction to reduce image residuals.'};
  if(!s.points)reset();
  const point=s.points[s.selected];
  const c={title:'Reconstruction controls',body:`<label class="control"><span>Select a landmark</span><select id="sselect">${names.map((n,i)=>`<option value="${i}" ${s.selected===i?'selected':''}>${n}</option>`).join('')}</select></label>`+range('sx','Selected point X',point.x,-2,2,.01)+range('sz','Selected point depth Z',point.z,.8,8,.01)+range('sc','Estimated camera 3 position',s.cam3,.25,3.5,.01)+checkbox('sview','Use camera 3 image',s.include3)+checkbox('sbad','Corrupt one camera 3 match',s.bad)+checkbox('struth','Reveal synthetic reference',s.showReference)+`<div class="actions"><button id="sstep" class="secondary">One fitting step</button><button id="sfit" class="primary">Refine reconstruction</button><button id="sreset" class="secondary">Reset estimate</button></div><p class="fit-status" id="sfit-status" role="status"></p><p class="hint">Blue camera 1 and camera 2 are fixed. Their known separation fixes the scale. The orange camera 3 position and all point coordinates can be fitted.</p>`};
  const v=`<div class="explain-first"><b>Why fit a scene?</b> Photographs provide 2D observations of the same landmarks, not their 3D coordinates. The three simplified image frames below show only those tracked landmarks. One set of estimated 3D points and camera positions must explain all the images at once. Change the reconstruction and watch its hollow projected markers move; then refine to bring them closer to the filled observations.</div>`+
    panel('Estimated cameras and 3D points','sscene','TOP-DOWN X-Z VIEW · POINT HEIGHT Y IS NOT SHOWN')+
    `<div class="panel"><div class="visual-title"><h3>Three images: observed vs projected landmarks</h3><small>COLOURS LINK THE SAME LANDMARK</small></div><svg id="splot" class="plot" viewBox="0 0 800 310" role="img" aria-label="Image observations and corresponding projected landmark estimates"></svg><div class="geometry-legend"><span><i class="swatch sfm-observed"></i> Filled: observed image point</span><span><i class="swatch sfm-projected"></i> Outline: projected estimate</span><span><i class="swatch sfm-residual"></i> Line: reprojection residual</span></div></div>`+
    `<div class="metrics">${metric('Mean reprojection error²','sloss','mean of squared 2D residuals')}${metric('Fitting steps','ssteps','accepted optimisation steps')}${metric('Observations','sobs','visible image points')}</div><div class="explainer" id="sfm-explanation"></div>`;
  let extra=`<details class="optional" id="affine-optional"><summary>Optional: How do image points lead to affine SfM?</summary><div class="optional-body" id="affine-content"></div></details>`;
  workspace.innerHTML=sectionShell(current,c,v,'The small scene is synthetic. All cameras have focal length 1 and the same orientation; camera 1, camera 2 and their 1 m baseline are fixed. Only camera 3 translation along X and the four 3D point coordinates are estimated. Point depths remain at least 0.8 m, camera 3 is constrained to 0.25-3.5 m, and the scene view rescales to keep estimates visible.',extra);
  const cameras=()=>s.include3?[0,baseline,s.cam3]:[0,baseline];
  const project=(point,camera)=>({u:focal*(point.x-camera)/point.z,v:focal*point.y/point.z});
  const observe=(j,i)=>{const q=project(truth[i],[0,baseline,2][j]);if(s.bad&&j===2&&i===2){q.u+=.22;q.v-=.12}return q};
  const residuals=()=>{const rows=[];cameras().forEach((cam,j)=>s.points.forEach((p,i)=>{const observed=observe(j,i),predicted=project(p,cam);rows.push({j,i,observed,predicted,du:predicted.u-observed.u,dv:predicted.v-observed.v})}));return rows};
  const loss=()=>{const rows=residuals();return rows.reduce((sum,r)=>sum+r.du*r.du+r.dv*r.dv,0)/rows.length};
  function solve(A,b){const n=b.length,M=A.map((row,i)=>[...row,b[i]]);for(let k=0;k<n;k++){let p=k;for(let i=k+1;i<n;i++)if(Math.abs(M[i][k])>Math.abs(M[p][k]))p=i;[M[p],M[k]]=[M[k],M[p]];if(Math.abs(M[k][k])<1e-12)return null;for(let i=k+1;i<n;i++){const f=M[i][k]/M[k][k];for(let j=k;j<=n;j++)M[i][j]-=f*M[k][j]}}const x=Array(n).fill(0);for(let i=n-1;i>=0;i--){let v=M[i][n];for(let j=i+1;j<n;j++)v-=M[i][j]*x[j];x[i]=v/M[i][i]}return x}
  function step(){
    const dim=13,A=Array.from({length:dim},()=>Array(dim).fill(0)),b=Array(dim).fill(0),cams=cameras(),rows=residuals(),before=loss();
    for(const r of rows){const p=s.points[r.i],cam=cams[r.j],u=Array(dim).fill(0),v=Array(dim).fill(0),k=3*r.i;u[k]=focal/p.z;u[k+2]=-focal*(p.x-cam)/(p.z*p.z);v[k+1]=focal/p.z;v[k+2]=-focal*p.y/(p.z*p.z);if(r.j===2)u[12]=-focal/p.z;
      for(const [jac,res] of [[u,r.du],[v,r.dv]])for(let a=0;a<dim;a++){b[a]-=jac[a]*res;for(let d=0;d<dim;d++)A[a][d]+=jac[a]*jac[d]}}
    for(let i=0;i<dim;i++)A[i][i]+=.002;
    const delta=solve(A,b);if(!delta)return false;
    const saved=s.points.map(p=>({...p})),oldCam=s.cam3;
    for(let alpha=1;alpha>=1/128;alpha/=2){s.points=saved.map((p,i)=>({x:p.x+alpha*delta[3*i],y:p.y+alpha*delta[3*i+1],z:Math.max(.8,p.z+alpha*delta[3*i+2])}));s.cam3=Math.max(.25,Math.min(3.5,oldCam+alpha*delta[12]));if(loss()<before-1e-12){s.steps++;return true}}
    s.points=saved;s.cam3=oldCam;return false;
  }
  function updateControls(){const p=s.points[s.selected],xs=document.getElementById('sx'),zs=document.getElementById('sz');xs.min=Math.min(-2,Math.floor(p.x*2)/2);xs.max=Math.max(2,Math.ceil(p.x*2)/2);zs.max=Math.max(8,Math.ceil(p.z));xs.value=p.x;zs.value=p.z;document.getElementById('sc').value=s.cam3;out('sx-value',p.x,2);out('sz-value',p.z,2);out('sc-value',s.cam3,2);document.getElementById('sbad').disabled=!s.include3;document.getElementById('sc').disabled=!s.include3;set('sfit-status',s.status);}
  const draw=()=>{
    const cams=cameras(),p=s.points[s.selected],xs=[0,baseline,...cams,...s.points.map(q=>q.x),...(s.showReference?truth.map(q=>q.x):[])],xmin=Math.min(...xs)-.6,xmax=Math.max(...xs)+.6,zmax=Math.max(8,...s.points.map(q=>q.z),...(s.showReference?truth.map(q=>q.z):[]))+.6,wx=x=>70+(x-xmin)/(xmax-xmin)*660,wy=z=>239-z/zmax*185;
    let g=`<rect x="35" y="18" width="730" height="225" rx="4" fill="#f7fbfe" stroke="#e1ebf3"/>`+line(50,239,750,239,'#aac3d2',1)+label(60,40,'Select a landmark to trace its projections','#678196',11);
    cams.forEach((cam,j)=>{const x=wx(cam),col=j===2?'#c17a3a':'#2f7395';g+=line(x,239,wx(p.x),wy(p.z),'#abc8d6',1.6)+`<path d="M ${x-8} 245 L ${x} 229 L ${x+8} 245 Z" fill="${col}"/>`+label(x-35,265,`CAM ${j+1}${j===2?' EST.':''}`,col,11)});
    if(s.showReference){truth.forEach((q,i)=>{g+=`<circle cx="${wx(q.x)}" cy="${wy(q.z)}" r="9" fill="none" stroke="#a6b7c2" stroke-width="2" stroke-dasharray="3 2"/>`});if(s.include3)g+=`<path d="M ${wx(2)-8} 245 L ${wx(2)} 229 L ${wx(2)+8} 245 Z" fill="none" stroke="#a6b7c2" stroke-width="2"/>`}
    s.points.forEach((q,i)=>{g+=dot(wx(q.x),wy(q.z),colours[i],i===s.selected?9:6)+label(wx(q.x)+10,wy(q.z)-8,names[i],colours[i],12)});set('sscene',g);
    const rows=residuals();let scale=Math.max(.8,...rows.flatMap(r=>[Math.abs(r.observed.u),Math.abs(r.observed.v),Math.abs(r.predicted.u),Math.abs(r.predicted.v)]))*1.15;
    let im='';for(let j=0;j<3;j++){const left=30+j*255,top=36,size=210,midX=left+size/2,midY=top+size/2;im+=`<rect x="${left}" y="${top}" width="${size}" height="${size}" rx="3" fill="${j<cams.length?'#f5faff':'#f5f5f5'}" stroke="#cbdde8"/>`+label(left+53,22,'CAMERA '+(j+1),'#54758e',12);if(j>=cams.length){im+=label(left+72,148,'NOT USED','#8b9ba7',12);continue}im+=line(midX,top+8,midX,top+size-8,'#dce9f0',1)+line(left+8,midY,left+size-8,midY,'#dce9f0',1);
      rows.filter(r=>r.j===j).forEach(r=>{const pos=q=>[midX+q.u/scale*(size/2-18),midY-q.v/scale*(size/2-18)],o=pos(r.observed),p=pos(r.predicted),col=colours[r.i];im+=line(o[0],o[1],p[0],p[1],col,r.i===s.selected?2.5:1.5)+`<circle cx="${p[0]}" cy="${p[1]}" r="${r.i===s.selected?8:6}" fill="white" stroke="${col}" stroke-width="2.5"/>`+dot(o[0],o[1],col,r.i===s.selected?6:5)+label(o[0]+7,o[1]-7,names[r.i],col,11)});
    }im+=label(290,290,'Filled: observed   ·   Outline: projected estimate','#668198',12);set('splot',im);
    out('sloss',loss(),5);out('ssteps',s.steps,0);out('sobs',rows.length,0);set('sfm-explanation',s.bad&&s.include3?'One observed point in camera 3 is deliberately incorrect. The optimiser still tries to fit it, so a low overall error can come at the expense of the estimated geometry.':s.include3?'A single 3D estimate is projected into every available image. A fitting step changes all four 3D points and camera 3 together to reduce the squared image residuals.':'Only the first two images are used. Fitting adjusts the four points; camera 3 is not fitted while its image is hidden.');updateControls();
  };
  document.getElementById('sselect').onchange=e=>{s.selected=Number(e.target.value);draw()};bindRange('sx',v=>{s.points[s.selected].x=v;s.status='Estimate changed manually. Fit again to reduce residuals.';draw()});bindRange('sz',v=>{s.points[s.selected].z=v;s.status='Estimate changed manually. Fit again to reduce residuals.';draw()});bindRange('sc',v=>{s.cam3=v;s.status='Estimate changed manually. Fit again to reduce residuals.';draw()});document.getElementById('sview').onchange=e=>{s.include3=e.target.checked;s.status='Observations changed. The current estimate has not been refitted.';draw()};document.getElementById('sbad').onchange=e=>{s.bad=e.target.checked;s.status='Observations changed. The current estimate has not been refitted.';draw()};document.getElementById('struth').onchange=e=>{s.showReference=e.target.checked;draw()};document.getElementById('sreset').onclick=()=>{reset();draw()};document.getElementById('sstep').onclick=()=>{s.status=step()?'One fitting step accepted.':'No lower-error step found.';draw()};document.getElementById('sfit').onclick=()=>{let accepted=0;for(let i=0;i<25;i++){if(!step())break;accepted++}s.status=accepted?`Refined using ${accepted} fitting steps.`:'No lower-error step found.';draw()};
  document.getElementById('affine-optional').addEventListener('toggle',e=>{if(e.target.open)affinePanel()});
  draw();
}

function affinePanel(){
  const stateA=state.affine, names=['A','B','C','D'], colours=['#248db6','#b96d3c','#8b6aa5','#3b9174'];
  const M=[[1,0,0],[0,1,0],[.8,0,.6],[0,1,0]], S=[[-1,0,1,0],[0,1,0,-1],[1,-1,1,-1]];
  const product=(a,b)=>a.map(row=>b[0].map((_,j)=>row.reduce((sum,x,k)=>sum+x*b[k][j],0)));
  const fmt=x=>Math.abs(x)<1e-10?'0':Number(x.toFixed(2)).toString();
  const reference=product(M,S);
  function factors(){const t=stateA.shear;return [M.map(r=>[r[0],r[0]*t+r[1],r[2]]),[S[0].map((v,i)=>v-t*S[1][i]),S[1],S[2]]];}
  function view(d,k){
    let content=`<line x1="30" y1="105" x2="250" y2="105" stroke="#c1d5e2"/><line x1="140" y1="20" x2="140" y2="190" stroke="#c1d5e2"/><text x="240" y="99" font-size="12" fill="#506c80">u</text><text x="145" y="28" font-size="12" fill="#506c80">v</text>`;
    names.forEach((name,i)=>{let x=140+d[2*k][i]*65,y=105-d[2*k+1][i]*65, selected=i===stateA.point;content+=`<circle cx="${x}" cy="${y}" r="${selected?10:6}" fill="${colours[i]}" stroke="${selected?'#102f48':'white'}" stroke-width="${selected?3:1.5}"/><text x="${x+12}" y="${y-9}" font-size="14" font-weight="700" fill="${colours[i]}">${name}</text>`});
    return `<div class="affine-image"><strong>Image ${k+1}</strong><svg viewBox="0 0 280 210" role="img" aria-label="Centred image ${k+1} with four labelled landmarks">${content}</svg></div>`;
  }
  const pair=d=>`<div class="affine-images">${view(d,0)}${view(d,1)}</div>`;
  function matrix(d,rows,selected){return `<div class="affine-table-wrap"><table class="affine-table"><thead><tr><th></th>${names.map((n,i)=>`<th class="${i===selected?'chosen':''}" style="color:${colours[i]}">${n}</th>`).join('')}</tr></thead><tbody>${d.map((row,i)=>`<tr><th scope="row">${rows[i]}</th>${row.map((v,j)=>`<td class="${j===selected?'chosen':''}">${fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
  function raw(a){return a.map(r=>r.map(v=>fmt(v).padStart(6)).join(' ')).join('\n')}
  function structure(q){
    let graph='<line x1="25" y1="120" x2="315" y2="120" stroke="#bfd3df"/><line x1="170" y1="20" x2="170" y2="220" stroke="#bfd3df"/><text x="302" y="113" font-size="12">X</text><text x="177" y="30" font-size="12">Y</text>';
    names.forEach((n,i)=>{let x=170+S[0][i]*60,y=120-S[1][i]*60,x2=170+q[0][i]*60,y2=120-q[1][i]*60;graph+=`<line x1="${x}" y1="${y}" x2="${x2}" y2="${y2}" stroke="${colours[i]}" stroke-width="2"/><circle cx="${x}" cy="${y}" r="5" fill="${colours[i]}"/><circle cx="${x2}" cy="${y2}" r="8" fill="white" stroke="${colours[i]}" stroke-width="3"/><text x="${x2+10}" y="${y2-8}" font-size="14" font-weight="700" fill="${colours[i]}">${n}</text>`});
    return `<svg viewBox="0 0 340 240" role="img" aria-label="Original and sheared 3D points shown in the X-Y plane">${graph}</svg>`;
  }
  // Each image plane is a geometric realisation of an affine 2 x 3 projection.
  // The dual vectors span a plane whose coordinates are exactly u and v.
  function cameraScene(m,q,k){
    const u=m[2*k],v=m[2*k+1], inner=(a,b)=>a.reduce((sum,x,i)=>sum+x*b[i],0), scale=(a,t)=>a.map(x=>x*t), add=(a,b)=>a.map((x,i)=>x+b[i]), cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
    const uu=inner(u,u),uv=inner(u,v),vv=inner(v,v),det=uu*vv-uv*uv;
    const eu=scale(add(scale(u,vv),scale(v,-uv)),1/det), ev=scale(add(scale(v,uu),scale(u,-uv)),1/det), normal=cross(u,v), unit=scale(normal,1/Math.sqrt(inner(normal,normal))), centre=scale(unit,-2.3);
    const plane=(x,y)=>add(centre,add(scale(eu,x),scale(ev,y)));
    const corners=[plane(-1.9,-1.45),plane(1.9,-1.45),plane(1.9,1.45),plane(-1.9,1.45)];
    const points=names.map((_,i)=>[q[0][i],q[1][i],q[2][i]]), image=points.map(p=>plane(inner(u,p),inner(v,p)));
    const proj=p=>[p[0]+.52*p[2],-p[1]+.30*p[2]], projected=[...corners,...points,...image].map(proj), xs=projected.map(p=>p[0]),ys=projected.map(p=>p[1]);
    const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys), sc=Math.min(285/(x1-x0||1),195/(y1-y0||1));
    const pt=p=>{const [x,y]=proj(p);return [160+(x-(x0+x1)/2)*sc,115+(y-(y0+y1)/2)*sc]}, xy=p=>pt(p).map(n=>n.toFixed(1)).join(',');
    let svg=`<polygon points="${corners.map(xy).join(' ')}" fill="#e3f1f6" stroke="#7b9eaf" stroke-width="1.5"/>`;
    // Dashed parallel rays connect each point to the corresponding image-plane coordinate.
    points.forEach((p,i)=>{const [x,y]=pt(p),[ix,iy]=pt(image[i]);svg+=`<line x1="${x}" y1="${y}" x2="${ix}" y2="${iy}" stroke="${colours[i]}" stroke-width="${i===stateA.point?2.5:1.4}" stroke-dasharray="4 3"/><circle cx="${ix}" cy="${iy}" r="${i===stateA.point?5.5:4}" fill="${colours[i]}"/><circle cx="${x}" cy="${y}" r="${i===stateA.point?7:5}" fill="white" stroke="${colours[i]}" stroke-width="2.5"/><text x="${x+8}" y="${y-7}" fill="${colours[i]}" font-weight="700" font-size="12">${names[i]}</text>`});
    const [cx,cy]=pt(centre);svg+=`<text x="${cx+5}" y="${cy+15}" fill="#45677d" font-size="11">image plane</text>`;
    return `<div class="affine-camera"><strong>Camera ${k+1}</strong><svg viewBox="0 0 320 230" role="img" aria-label="Camera ${k+1} affine image plane and parallel rays from the transformed landmarks">${svg}</svg><small>Camera ${k+1}: transformed points and parallel projection onto its image plane</small></div>`;
  }
  const cameraPair=(m,q)=>`<div class="affine-camera-pair">${cameraScene(m,q,0)}${cameraScene(m,q,1)}</div>`;
  function render(){
    const step=stateA.step, selected=stateA.point, n=names[selected], [m,q]=factors(), d2=product(m,q), max=Math.max(...reference.flatMap((row,i)=>row.map((v,j)=>Math.abs(v-d2[i][j]))));
    const picker=`<div class="affine-picker" aria-label="Choose a landmark"><span>Follow landmark:</span>${names.map((n,i)=>`<button type="button" data-af-point="${i}" aria-pressed="${i===selected}" style="--point-colour:${colours[i]}">${n}</button>`).join('')}</div>`;
    const steps=['Image points','Stack coordinates','Ambiguity'];
    let content=`<p>Follow four matched landmarks through a small, centred affine SfM example.</p><nav class="affine-steps" aria-label="Factorisation steps">${steps.map((s,i)=>`<button type="button" data-af-step="${i}" aria-pressed="${i===step}">${i+1}. ${s}</button>`).join('')}</nav>`;
    if(step===0){content+=`<h3>1. Match the same points in two images</h3><p>Each coloured letter is one landmark seen in both images. Select a letter to follow its two image coordinates. The coordinate origin is at the centre of each image.</p>${picker}${pair(reference)}<p>Each image contributes a horizontal coordinate <em>u</em> and a vertical coordinate <em>v</em> for every landmark. These are affine projections of four 3D points.</p>`;}
    if(step===1){content+=`<h3>2. Put the measurements into a matrix</h3><p>Each column follows one landmark across the images. Each pair of rows records one image's <em>u</em> and <em>v</em> coordinates. Select a landmark to see its column and its image points.</p>${picker}${pair(reference)}<h4>Measurement matrix D</h4>${matrix(reference,['Image 1 u','Image 1 v','Image 2 u','Image 2 v'],selected)}<p>For landmark <strong>${n}</strong>, its highlighted column contains (${reference.map(r=>fmt(r[selected])).join(', ')})<sup>T</sup>. The entries are the same coordinates shown above.</p><div class="formula">D (2m × n) = M (2m × 3) · S (3 × n)</div><p><strong>D</strong> is the measurement matrix of image coordinates. <strong>M</strong> is the motion matrix, containing the camera projection factors for all views. <strong>S</strong> is the shape matrix, containing the 3D landmark coordinates.</p><p><strong>Why rank at most 3?</strong> Every column of the measurement matrix D is a weighted sum of the three columns of the motion matrix M: its weights are the landmark's three coordinates in the shape matrix S. The columns of D therefore lie in a space of dimension at most 3. Degenerate scenes can have lower rank.</p><details><summary>Show the factors for this example</summary><p>These are one exact pair of factors, chosen to construct the example. They are not necessarily the factors returned by SVD.</p><div class="affine-factors"><div><strong>M: image axes</strong><pre>${raw(M)}</pre></div><div><strong>S: 3D points A-D</strong><pre>${raw(S)}</pre></div></div></details>`;}
    if(step===2){content+=`<h3>3. Different structures can explain the same images</h3><p>Move the shear. The hollow markers show transformed 3D points; the filled markers show the original points. The camera factors change together with the structure, so the image measurements stay fixed.</p><label class="control"><span>Shear <output id="af-shear-value">${fmt(stateA.shear)}</output></span><input id="af-shear" type="range" min="-1.5" max="1.5" step="0.1" value="${stateA.shear}"></label><div class="affine-structure"><strong>3D structure - X-Y slice</strong><div id="af-shape">${structure(q)}</div><p>Filled: original &nbsp; · &nbsp; Hollow: transformed. Z is unchanged.</p></div>${picker}<h4>How each affine camera sees the transformed structure</h4><p>Each panel shows the transformed points, one image plane and parallel projection rays. Filled dots on the planes are the image measurements. Follow the selected landmark along its dashed ray, then compare its location in the images below.</p><div id="af-cameras">${cameraPair(m,q)}</div><p><strong>Image coordinates using the transformed camera factors</strong></p><div id="af-views">${pair(d2)}</div><p>The plane placement is chosen for illustration. Affine cameras have parallel rays rather than a finite camera centre; the planes themselves can shear as the camera factors change.</p><div class="formula">D = MS = (MC)(C⁻¹S)</div><p id="af-error">Largest change in an image coordinate: ${max.toExponential(2)} (numerical precision).</p><p>This is an ambiguity of <strong>affine</strong> factorisation. The transformed cameras need not remain orthographic. Additional metric or camera constraints can reduce the ambiguity.</p><details><summary>Show transformed factors and measurements</summary><div class="affine-factors"><div><strong>M′ = MC</strong><pre id="af-m">${raw(m)}</pre></div><div><strong>S′ = C⁻¹S</strong><pre id="af-s">${raw(q)}</pre></div></div><strong>Measurements M′S′</strong><div id="af-d">${matrix(d2,['Image 1 u','Image 1 v','Image 2 u','Image 2 v'],selected)}</div></details>`;}
    content+=`<div class="affine-actions">${step>0?'<button type="button" data-af-step="'+(step-1)+'">Previous</button>':''}${step<2?'<button type="button" data-af-step="'+(step+1)+'">Next step</button>':''}</div><details class="affine-question"><summary>Worked question</summary><p>Why does centring remove image translations, and why can different factors describe the same measurements?</p><p>Subtracting the mean image coordinate removes a translation shared by all points in that image. If C is invertible, inserting CC⁻¹ between M and S changes both factors but leaves their product D unchanged. Image measurements alone therefore do not fix the affine structure.</p></details>`;
    document.getElementById('affine-content').innerHTML=content;
    document.querySelectorAll('[data-af-step]').forEach(el=>el.onclick=()=>{stateA.step=Number(el.dataset.afStep);render()});
    document.querySelectorAll('[data-af-point]').forEach(el=>el.onclick=()=>{stateA.point=Number(el.dataset.afPoint);render()});
    const slider=document.getElementById('af-shear');if(slider)slider.oninput=e=>{stateA.shear=Number(e.target.value);const [m,q]=factors(), d=product(m,q), err=Math.max(...reference.flatMap((r,i)=>r.map((v,j)=>Math.abs(v-d[i][j]))));document.getElementById('af-shear-value').textContent=fmt(stateA.shear);document.getElementById('af-shape').innerHTML=structure(q);document.getElementById('af-cameras').innerHTML=cameraPair(m,q);document.getElementById('af-views').innerHTML=pair(d);document.getElementById('af-error').textContent=`Largest change in an image coordinate: ${err.toExponential(2)} (numerical precision).`;document.getElementById('af-m').textContent=raw(m);document.getElementById('af-s').textContent=raw(q);document.getElementById('af-d').innerHTML=matrix(d,['Image 1 u','Image 1 v','Image 2 u','Image 2 v'],stateA.point)};
  }
  render();
}

function learning(){
  const s=state.prior, scene=state.ambiguity, stereo=state.twoview;
  const h=2*scene.f*scene.x/scene.z, f=scene.f;
  const c={title:'Choose assumptions and evidence',body:checkbox('penabled','Use an object-size prior',s.usePrior)+range('pmean','Typical object height',s.mean,.5,3.5,.25,' m')+range('psigma','Spread of size prior',s.sigma,.2,1,.05,' m')+range('pactual','Actual object height',2*scene.x,.5,4,.05,' m')+checkbox('pview','Add the second camera',s.second)+range('pbase','Camera baseline B',stereo.baseline,0,2,.05,' m')+range('pnoise','Disparity measurement error',stereo.noise,-.08,.08,.005)+`<p class="hint">Actual height is revealed only as a reference. Changing it also changes the distance so the first image remains fixed.</p>`};
  const v=`<div class="explain-first"><b>One image, three kinds of information.</b> The first camera gives a ray, not a distance. A size prior favours points along that ray. A translated second camera contributes another ray. Turn the prior and the second camera on and off to compare their roles.</div><div class="panel"><div class="visual-title"><h3>Both cameras in one coordinate system</h3><small>FIRST CAMERA AT (0, 0) · AXES SCALED</small></div><svg id="pgeometry" class="plot" viewBox="0 0 800 340" role="img" aria-label="Canonical camera coordinates, rays and candidate geometry"></svg><div class="geometry-legend"><span><i class="swatch first-ray"></i> First camera ray</span><span><i class="swatch second-ray"></i> Measured second camera ray</span><span><i class="swatch reference-point"></i> True endpoint (teaching reference)</span><span><i class="swatch prior-point"></i> Prior mean</span><span><i class="swatch stereo-point"></i> Stereo intersection</span><span><i class="swatch combined-point"></i> Prior + stereo mean</span></div></div>`+panel('Which distances are supported?','pplot','FINITE SET OF CANDIDATES')+`<div class="metrics">${metric('Prior-only mean Z','pprior','object-size assumption')}${metric('Current estimate Z','pestimate','selected information')}${metric('True Z','ptruth','teaching reference')}</div><div class="formula" id="pformula"></div><div class="explainer" id="pinfo"></div>`;
  const extra=`<details class="optional" id="shortcut-optional"><summary>Optional extension: When a model learns a shortcut</summary><div class="optional-body"><p>A separate example tests how a training correlation can fail on held-out data. It is about generalisation rather than how the size prior above is obtained.</p><div id="shortcut-workspace"></div><div class="qcard optional-question"><h3>Optional question</h3><p>${current.optional_question.scenario}</p><ol type="a"><li>${current.optional_question.a}</li><li>${current.optional_question.b}</li></ol><details><summary>Show worked answer</summary><p><b>(a)</b> ${current.optional_question.answer_a}</p><p><b>(b)</b> ${current.optional_question.answer_b}</p></details></div></div></details>`;
  workspace.innerHTML=sectionShell(current,c,v,'This 2D epipolar slice uses the first camera as the origin, +Z away from the cameras and +X along the baseline. Candidate object heights are 0.5-4.0 m in 0.25 m steps. The second-view likelihood assumes Gaussian disparity error with standard deviation 0.03.',extra);
  const sizes=Array.from({length:15},(_,i)=>.5+i*.25), sigmaD=.03;
  const softmax=logs=>{const m=Math.max(...logs),v=logs.map(x=>Math.exp(x-m)),z=v.reduce((a,b)=>a+b,0);return v.map(x=>x/z)};
  const draw=()=>{
    const actual=2*scene.x, truth=scene.z, depths=sizes.map(H=>f*H/h), measured=f*stereo.baseline/truth+stereo.noise;
    const logPrior=sizes.map(H=>s.usePrior?-.5*((H-s.mean)/s.sigma)**2:0), weights=softmax(logPrior);
    const validStereo=s.second&&stereo.baseline>0&&measured>0, triangulated=validStereo?f*stereo.baseline/measured:NaN;
    const post=softmax(logPrior.map((w,i)=>w-(s.second&&stereo.baseline>0?.5*((f*stereo.baseline/depths[i]-measured)/sigmaD)**2:0)));
    const mean=(v,w)=>v.reduce((a,x,i)=>a+x*w[i],0), prior=mean(depths,weights);
    const hasLikelihood=s.second&&stereo.baseline>0;
    const estimate=s.usePrior?(hasLikelihood?mean(depths,post):prior):(validStereo?triangulated:NaN);
    const shownPrior=s.usePrior?prior:NaN, showStereo=s.second&&validStereo;
    const displayDepth=Math.max(5,truth,Number.isFinite(shownPrior)?shownPrior:0,showStereo&&triangulated<25?triangulated:0,Number.isFinite(estimate)&&estimate<25?estimate:0)*1.18;
    const originX=335, baseY=278, xscale=95, zscale=220/displayDepth, px=x=>originX+x*xscale, py=z=>baseY-z*zscale, ratio=scene.x/truth, u1=f*ratio, u2=u1-measured;
    let g=`<defs><clipPath id="canonical-clip"><rect x="35" y="25" width="730" height="255"/></clipPath></defs><rect x="35" y="25" width="730" height="255" rx="4" fill="#f7fbfe" stroke="#dfeaf1"/>`;
    g+=line(55,baseY,745,baseY,'#b2c7d5',1)+line(originX,baseY,originX,35,'#b2c7d5',1,'3 4')+label(710,303,'+X','#658093',11)+label(originX+8,39,'+Z','#658093',11);
    g+=`<g clip-path="url(#canonical-clip)">`+line(px(0),py(0),px(ratio*displayDepth),py(displayDepth),'#258db5',2.5);
    if(s.second)g+=line(px(stereo.baseline),py(0),px(stereo.baseline+(u2/f)*displayDepth),py(displayDepth),'#d28b43',2.5);
    g+=line(px(-scene.x),py(truth),px(scene.x),py(truth),'#a9b9c5',5)+`<circle cx="${px(scene.x)}" cy="${py(truth)}" r="7" fill="#fff" stroke="#738d9e" stroke-width="2"/>`;
    if(Number.isFinite(shownPrior))g+=dot(px(ratio*shownPrior),py(shownPrior),'#258db5',6);
    if(showStereo)g+=`<path d="M ${px(ratio*triangulated)} ${py(triangulated)-8} l -7 13 h 14 Z" fill="#d28b43" stroke="#fff" stroke-width="1.2"/>`;
    if(s.usePrior&&hasLikelihood&&Number.isFinite(estimate))g+=`<rect x="${px(ratio*estimate)-5}" y="${py(estimate)-5}" width="10" height="10" transform="rotate(45 ${px(ratio*estimate)} ${py(estimate)})" fill="#8059a4"/>`;
    g+='</g>';
    g+=`<path d="M ${px(0)-8} ${baseY+7} L ${px(0)} ${baseY-8} L ${px(0)+8} ${baseY+7} Z" fill="#286f91"/>`+label(px(0)-45,319,'CAMERA 1 (0, 0)','#3f6880',11);
    if(s.second)g+=`<path d="M ${px(stereo.baseline)-8} ${baseY+7} L ${px(stereo.baseline)} ${baseY-8} L ${px(stereo.baseline)+8} ${baseY+7} Z" fill="#bd793c"/>`+label(px(stereo.baseline)+10,305,'CAMERA 2 (B, 0)','#a16c3a',11);
    if(s.second&&!validStereo)g+=label(45,48,stereo.baseline===0?'Zero baseline: rays do not triangulate.':'No positive-depth intersection for this disparity.','#a16c3a',12);
    if(Number.isFinite(estimate)&&estimate>=25)g+=label(45,65,'Estimated intersection is beyond the displayed region.','#a16c3a',11);
    set('pgeometry',g);
    const peak=Math.max(...weights,...(hasLikelihood?post:[]));
    let chart=line(68,225,755,225,'#a7c2d2',1)+label(20,35,'weight','#617e92',11);
    depths.forEach((z,i)=>{let x=90+i*44,ph=weights[i]/peak*155,posth=post[i]/peak*155;chart+=`<rect x="${x}" y="${225-ph}" width="${hasLikelihood?15:24}" height="${ph}" fill="#3092bb" opacity=".8"/>`;if(hasLikelihood)chart+=`<rect x="${x+16}" y="${225-posth}" width="15" height="${posth}" fill="#cf8c49"/>`;if(i%2===0)chart+=label(x-4,248,fmt(z,1),'#647f92',10)});
    const trueX=90+(actual-.5)/.25*44;chart+=label(250,271,'Candidate distance Z (m)','#5d7890',11)+line(trueX,51,trueX,225,'#8b6d61',1.5,'4 4')+label(trueX+5,48,'TRUE','#8b6d61',10);set('pplot',chart);
    out('pprior',s.usePrior?fmt(prior,2):'off');out('pestimate',Number.isFinite(estimate)?fmt(estimate,2):'undetermined');out('ptruth',truth);out('pmean-value',s.mean,2);out('psigma-value',s.sigma,2);out('pactual-value',actual,2);out('pbase-value',stereo.baseline,2);out('pnoise-value',stereo.noise,3);
    set('pformula',`First view: h = fH / Z = ${fmt(h,3)}. ${s.second?'Measured disparity d = '+fmt(measured,3)+'; stereo depth fB / d = '+(validStereo?fmt(triangulated,2):'undefined')+'.':'The second camera is not used.'}`);
    set('pinfo',!s.usePrior&&!s.second?'A single ray contains many possible points. With neither the size prior nor a second view, distance is undetermined. Equal bars only enumerate a finite set of candidates; they are not a unique uninformative prior.':s.second&&!validStereo?(stereo.baseline===0?'A zero baseline gives no depth-dependent disparity. The second camera does not triangulate.':s.usePrior?'The measured ray has no positive-depth intersection. The purple marker still shows the finite-candidate prior and likelihood update; it is not a ray intersection.':'The measured disparity does not yield a positive-depth intersection.'):s.second?(s.usePrior?'The purple diamond is the mean of the discrete prior-and-likelihood weights. The orange triangle is the direct ray intersection. A noisy match can move both.':'With no size weighting, the orange triangle is the direct two-ray triangulation. The plotted bars use equal weights over the finite candidates for illustration, not a coordinate-invariant uninformative prior.'):'The blue point is the mean implied by the size prior. It is a plausible guess, not a measurement of the true endpoint.');
    document.getElementById('pmean').disabled=!s.usePrior;document.getElementById('psigma').disabled=!s.usePrior;document.getElementById('pbase').disabled=!s.second;document.getElementById('pnoise').disabled=!s.second;syncShared();
  };
  bindRange('pmean',v=>{s.mean=v;draw()});bindRange('psigma',v=>{s.sigma=v;draw()});bindRange('pactual',v=>{const H=Math.max(.5,h/f,Math.min(4,9*h/f,v));scene.x=H/2;scene.z=f*H/h;document.querySelector('#pactual').value=H;draw()});bindRange('pbase',v=>{stereo.baseline=v;draw()});bindRange('pnoise',v=>{stereo.noise=v;draw()});document.querySelector('#penabled').onchange=e=>{s.usePrior=e.target.checked;draw()};document.querySelector('#pview').onchange=e=>{s.second=e.target.checked;draw()};
  const optional=document.querySelector('#shortcut-optional');optional.addEventListener('toggle',()=>{if(optional.open&&!document.querySelector('#shortcut-workspace').hasChildNodes())shortcut()});draw();
}
function shortcut(){
  const s=state.shortcut;
  const lambda=.01;
  const c={title:'1. Choose training data',body:checkbox('lextra','Add swapped-colour examples',s.extra)+`<div class="actions"><button class="primary" id="lfit">Fit model to training data</button><button class="secondary" id="lreset">Reset weights</button></div><p class="hint">Changing the training set does not refit the model. Press <b>Fit model</b> again to calculate new weights.</p><p class="fit-status" id="lstatus" role="status"></p>`};
  const v=`<div class="explain-first"><b>What is being learned?</b> A small regression model predicts distance from two inputs measured in each image: apparent object height and colour. It has two fitted weights. The training set initially contains only near red objects and far blue objects, so those cues are correlated. Fit the model, then test whether it works when colours are swapped. Fitting minimises mean squared error plus 0.01 times the sum of squared weights; this small penalty selects a stable solution when the cues are redundant.</div><div class="formula" id="lformula"></div><div class="panel"><div class="visual-title"><h3>2. Training images and targets</h3><small>SYNTHETIC · SAME 2 m OBJECT SIZE</small></div><div id="ltraining" class="cue-cards"></div></div><div class="panel"><div class="visual-title"><h3>3. What did the fitted model learn?</h3><small>SOLID: PREDICTIONS · MARKERS: TRUE DEPTHS</small></div>${svg('lplot','Predicted depth as a function of image height for red and blue objects')}<div class="geometry-legend"><span><i class="swatch colour-red"></i> Red object</span><span><i class="swatch colour-blue"></i> Blue object</span><span><i class="swatch train-marker"></i> Training target</span><span><i class="swatch test-marker"></i> Held-out target</span></div><p class="hint">Move from left to right: the object takes up more of the image. Coloured curves show the model's current prediction. The crosses are held-out examples, never used for fitting.</p></div><div class="panel"><div class="visual-title"><h3>4. Test on swapped colours</h3><small>HELD OUT FROM FITTING</small></div><div id="lheldout" class="cue-cards"></div></div><div class="metrics">${metric('Weight on image size','lweight-geometry','w_size')}${metric('Weight on colour','lweight-colour','w_colour')}${metric('Training MSE','ltrain','current training data, m²')}${metric('Held-out MSE','ltest','never used for fitting, m²')}</div><div class="explainer" id="linsight"></div>`;
  document.querySelector('#shortcut-workspace').innerHTML=`<div class="lab"><aside class="controls"><h3>${c.title}</h3>${c.body}</aside><div class="viz">${v}</div></div><p class="hint">The inverse-height feature is informative in this controlled dataset because the physical object size and focal length are fixed and known. The model is deliberately linear; it illustrates supervised fitting and a data shortcut, not an end-to-end depth network.</p>`;
  const training=()=>s.extra?[{colour:'red',z:2},{colour:'blue',z:6},{colour:'blue',z:2},{colour:'red',z:6}]:[{colour:'red',z:2},{colour:'blue',z:6}];
  const heldout=[{colour:'blue',z:2.5},{colour:'red',z:5.5}];
  const height=sample=>2/sample.z, sign=sample=>sample.colour==='red'?-1:1, sizeFeature=sample=>1/height(sample)-2;
  const predict=sample=>4+s.wg*sizeFeature(sample)+s.wc*sign(sample);
  const mse=data=>data.reduce((sum,x)=>sum+(predict(x)-x.z)**2,0)/data.length;
  const fit=()=>{
    const data=training(),n=data.length;
    let gg=lambda,cc=lambda,gc=0,gy=0,cy=0;
    for(const sample of data){const g=sizeFeature(sample),c=sign(sample),target=sample.z-4;gg+=g*g/n;cc+=c*c/n;gc+=g*c/n;gy+=g*target/n;cy+=c*target/n}
    const determinant=gg*cc-gc*gc;
    s.wg=(gy*cc-cy*gc)/determinant;s.wc=(cy*gg-gy*gc)/determinant;s.fitted=true;s.fitExtra=s.extra;
  };
  const card=(sample,isTest)=>{const h=height(sample),colour=sample.colour==='red'?'#bd6357':'#4a8eb8',pixels=80*h;return `<div class="cue-card image-example"><div class="object-image" role="img" aria-label="Synthetic ${sample.colour} object, apparent height ${fmt(h,2)}"><div class="object-silhouette" style="height:${pixels}px;width:${Math.max(10,pixels*.35)}px;background:${colour}"></div></div><div class="cue-name">${sample.colour} object · image height ${fmt(h,2)}</div><div class="cue-values"><span>True depth <b>${fmt(sample.z,2)} m</b></span><span>Model predicts <b>${fmt(predict(sample),2)} m</b></span></div>${isTest?'<small class="heldout-label">Not used for fitting</small>':''}</div>`};
  const drawPlot=()=>{
    const x=h=>85+(h-.25)/.8*625, y=z=>235-z*27;
    let g=`<defs><clipPath id="shortcut-clip"><rect x="85" y="38" width="625" height="197"/></clipPath></defs>`+line(85,235,710,235,'#90adbf',1)+line(85,45,85,235,'#90adbf',1)+label(18,50,'depth (m)','#617e92',11)+label(330,270,'apparent image height h','#617e92',11);
    [0,2,4,6].forEach(z=>{g+=line(85,y(z),710,y(z),'#e1ebf1',1)+label(58,y(z)+4,String(z),'#68849a',10)});
    [.3,.5,.7,.9,1].forEach(h=>{g+=label(x(h)-8,251,fmt(h,1),'#68849a',10)});
    g+='<g clip-path="url(#shortcut-clip)">';
    for(const [colour,c] of [['#bd6357',-1],['#4a8eb8',1]]){let points=[];for(let h=.26;h<=1.05;h+=.01){const z=4+s.wg*(1/h-2)+s.wc*c;points.push(`${x(h)},${y(z)}`)}g+=`<polyline points="${points.join(' ')}" fill="none" stroke="${colour}" stroke-width="2.5"/>`}
    for(const sample of training()){const cx=x(height(sample)),cy=y(sample.z),colour=sample.colour==='red'?'#bd6357':'#4a8eb8';g+=`<circle cx="${cx}" cy="${cy}" r="6" fill="${colour}" stroke="white" stroke-width="1.5"/>`}
    for(const sample of heldout){const cx=x(height(sample)),cy=y(sample.z),colour=sample.colour==='red'?'#bd6357':'#4a8eb8';g+=line(cx-5,cy-5,cx+5,cy+5,colour,3)+line(cx-5,cy+5,cx+5,cy-5,colour,3)}
    return g+'</g>';
  };
  const draw=()=>{
    set('ltraining',training().map(v=>card(v,false)).join(''));set('lheldout',heldout.map(v=>card(v,true)).join(''));set('lplot',drawPlot());
    out('lweight-geometry',s.wg,3);out('lweight-colour',s.wc,3);out('ltrain',mse(training()),4);out('ltest',mse(heldout),4);
    const stale=s.fitted&&s.fitExtra!==s.extra;
    set('lstatus',!s.fitted?'Not fitted yet. Both weights start at zero.':stale?'Training data changed. Predictions still use the previous fit; press Fit model again.':'Fitted to the currently selected training data.');
    set('lformula',`Model: predicted depth = 4 + (${fmt(s.wg,3)}) × (1/h − 2) + (${fmt(s.wc,3)}) × colour, where red = −1 and blue = +1.`);
    set('linsight',!s.fitted?'Fit the model to see how both correlated inputs can receive weight.':stale?'The displayed weights have not been refitted after the dataset change.':s.extra?'Swapped-colour training examples break the correlation. After refitting, the colour weight becomes small and the held-out predictions improve.':'With only two correlated examples, many combinations of size and colour weights fit almost equally well. The held-out crosses reveal the colour dependence.');
  };
  document.querySelector('#lfit').onclick=()=>{fit();draw()};document.querySelector('#lreset').onclick=()=>{s.wg=0;s.wc=0;s.fitted=false;s.fitExtra=null;draw()};document.querySelector('#lextra').onchange=e=>{s.extra=e.target.checked;draw()};draw();
}
// A small known scene used in both experiments: a pole in front of a wall.
function poleImage(poleDepth,wallDepth,kind='solid',markMissing=false){
  const depthColour=z=>{const t=Math.max(0,Math.min(1,(z-2)/10));return `rgb(${Math.round(42+173*t)},${Math.round(91+141*t)},${Math.round(119+125*t)})`};
  let g=`<rect x="20" y="15" width="240" height="180" rx="2" fill="${depthColour(wallDepth)}" stroke="#a8c0cf"/>`;
  if(kind==='points'){
    for(let y=25;y<=185;y+=16)for(let x=30;x<=250;x+=16){let pole=x>=122&&x<=154&&y>=45&&y<=165;g+=`<circle cx="${x}" cy="${y}" r="2.7" fill="${pole?'#174e6d':'#7aa0b4'}"/>`;}
  }else if(kind==='gaussian'){
    for(let y=35;y<=175;y+=35)for(let x=40;x<=240;x+=40)g+=`<ellipse cx="${x}" cy="${y}" rx="20" ry="16" fill="#a8d5e5" fill-opacity=".45" stroke="#5b96b1"/>`;
    for(let y=55;y<=155;y+=25)g+=`<ellipse cx="140" cy="${y}" rx="15" ry="20" fill="#288daf" fill-opacity=".42" stroke="#207899"/>`;
  }else if(poleDepth!==null){g+=`<rect x="127" y="43" width="26" height="125" fill="${depthColour(poleDepth)}"/>`;}
  if(markMissing)g+='<rect x="127" y="43" width="26" height="125" fill="none" stroke="#b35148" stroke-width="2" stroke-dasharray="5 4"/>';
  return `<svg viewBox="0 0 280 215" role="img" aria-label="Front view of a narrow pole in front of a wall">${g}</svg>`;
}
function sceneCameraImage(){
  // Colour and painted markings describe appearance, not extra geometry.
  return `<svg viewBox="0 0 280 215" role="img" aria-label="Camera image of a painted orange pole in front of a cream wall with blue painted shapes"><rect x="20" y="15" width="240" height="180" rx="2" fill="#f2e4c8" stroke="#c5bcae"/><path d="M20 150 L20 120 L85 90 L120 108 L120 137 L85 118 Z M160 55 L210 35 L260 55 L260 78 L210 58 L160 78 Z" fill="#88b7b8"/><circle cx="69" cy="55" r="16" fill="#e8b971"/><circle cx="216" cy="131" r="19" fill="#e4ad87"/><rect x="127" y="43" width="26" height="125" fill="#bc694c"/><path d="M127 65 H153 M127 88 H153 M127 111 H153 M127 134 H153" stroke="#f3dcb8" stroke-width="5"/></svg>`;
}
function representations(){
  const s=state.representations;
  const c={title:'Explore the scene',body:`<label class="control"><span>Representation</span><select id="rmode"><option value="depth">Depth map</option><option value="points">Point map</option><option value="occupancy">Occupancy field</option><option value="gaussian">Gaussian primitives</option></select></label><label class="control"><span>What would you like to inspect?</span><select id="rquery"><option value="front">Visible front of pole</option><option value="rear">Hidden back of pole</option><option value="empty">Empty space in front of pole</option><option value="wall">Visible wall</option></select></label><p class="hint">The reference scene is known in this teaching example. A prediction from one image does not automatically know the hidden geometry.</p>`};
  const v=`<div class="explain-first"><b>Question:</b> What information does the selected representation store about a pole in front of a wall? Choose a location and compare the answer with the reference.</div><div class="scene-grid"><div class="scene-card"><h3>Reference scene</h3><p>Camera image (colour)</p>${sceneCameraImage()}<p>Painted pole at 2 m; wall at 6 m. The colours and patterns are surface paint.</p><div id="reference-slice"></div></div><div class="scene-card"><h3 id="r-title"></h3><p id="r-description"></p><div id="r-visual"></div><div id="r-legend"></div></div></div><div class="answer-card"><strong id="r-question"></strong><p id="r-answer"></p></div><div class="explainer" id="rinfo"></div>`;
  workspace.innerHTML=sectionShell(current,c,v,'The reference is synthetic. An output representation specifies what can be encoded, not whether a prediction is correct.');
  const mode=document.querySelector('#rmode'),query=document.querySelector('#rquery');mode.value=s.mode;query.value=s.queryLocation||'front';
  function slice(q,occupancy=false){
    const coords={front:[140,77],rear:[140,106],empty:[140,48],wall:[215,166]};const [qx,qy]=coords[q];
    return `<svg class="slice-plot" viewBox="0 0 280 205" role="img" aria-label="Top-down slice from camera through pole to wall, showing the selected location"><text x="10" y="15" font-size="12" fill="#365d76">TOP-DOWN SLICE</text><path d="M 129 25 L 151 25 L 140 37 Z" fill="#305d76"/><text x="157" y="32" font-size="11" fill="#365d76">camera</text><line x1="35" y1="166" x2="245" y2="166" stroke="#789bae" stroke-width="4"/><text x="207" y="183" font-size="11" fill="#365d76">wall</text><rect x="125" y="77" width="30" height="29" fill="${occupancy?'#85bfd3':'#d5e5ed'}" stroke="#287c9e" stroke-width="2"/><line x1="125" y1="106" x2="155" y2="106" stroke="#567a8c" stroke-dasharray="4 3"/><text x="164" y="94" font-size="11" fill="#365d76">pole</text><line x1="140" y1="37" x2="140" y2="77" stroke="#7299ad" stroke-dasharray="4 4"/><circle cx="${qx}" cy="${qy}" r="7" fill="#e89948" stroke="white" stroke-width="2"/><text x="${Math.min(qx+11,230)}" y="${qy-8}" font-size="11" fill="#9b5b1e">query</text></svg>`;
  }
  function draw(){
    const q=query.value; s.queryLocation=q;s.mode=mode.value;const labels={front:'Visible front of the pole',rear:'Hidden back of the pole',empty:'Empty space in front of the pole',wall:'Visible wall'};
    let title='',description='',visual='',answer='',note='';
    if(s.mode==='depth'){
      title='Depth map';description='One depth value for the first visible surface at each pixel.';visual=poleImage(2,6);note='With known calibration and depth convention, a depth map can be back-projected. It does not directly store the occluded back of the pole.';
      answer={front:'Stored: the pole pixel has depth 2 m.',rear:'Not observed: the pole blocks this surface. The depth map stores the front at 2 m.',empty:'No occupancy label is stored. Under an ideal first-surface model, the part of a measured ray before the surface can be inferred as free.',wall:'Stored where visible: a wall pixel has depth 6 m. The wall behind the pole is occluded.'}[q];
    }else if(s.mode==='points'){
      title='Point map';description='Top-down slice: each dot is a back-projected visible 3D sample.';visual=`<svg viewBox="0 0 280 205" role="img" aria-label="Top-down point samples on the visible pole and wall"><path d="M 129 25 L 151 25 L 140 37 Z" fill="#305d76"/><text x="157" y="32" font-size="11" fill="#365d76">camera</text>${Array.from({length:15},(_,i)=>i>=6&&i<=8?'':`<circle cx="${42+i*14}" cy="166" r="3" fill="#3886a4"/>`).join('')}${[128,134,140,146,152].map(x=>`<circle cx="${x}" cy="77" r="3" fill="#1a698a"/>`).join('')}<text x="160" y="78" font-size="11" fill="#365d76">pole front</text><text x="185" y="182" font-size="11" fill="#365d76">visible wall</text></svg>`;note='The samples lie on visible surfaces. A point map need not contain a closed surface or the occluded back.';
      answer={front:'Stored as a visible 3D point at the front of the pole.',rear:'Not stored by this visible-surface point map: the rear is occluded.',empty:'No point is stored there. Missing points alone do not constitute an explicit occupancy label.',wall:'Visible wall locations are stored as 3D points; the wall behind the pole is not seen.'}[q];
    }else if(s.mode==='occupancy'){
      title='Occupancy field';description='A value at a 3D query location: inside or outside the pole in this reference field.';visual=slice(q,true);note='An occupancy field can encode hidden geometry, but a field predicted from one image must infer it from learned assumptions or other evidence.';
      answer={front:'On the surface: the value depends on the boundary convention. Nearby points can be queried inside or outside.',rear:'Representable as the back boundary, although it is hidden in the image. Its correct position must be inferred or observed separately.',empty:'Outside: the query lies in free space in the known reference field.',wall:'This example models the pole as the solid object; the wall is background and is outside the pole occupancy.'}[q];
    }else{
      title='Gaussian primitives';description='Soft 3D kernels are projected into the image; the ellipses illustrate their footprints.';visual=poleImage(2,6,'gaussian');note='This schematic represents visible surfaces with Gaussians. Rendering from another view is possible, but a good image alone does not guarantee an accurate or watertight surface.';
      answer={front:'The rendered pole is supported by projected Gaussian footprints; there is no single explicit surface point per pixel.',rear:'Not determined by this visible-surface illustration. Additional primitives could encode the back, but it must be inferred or observed.',empty:'The primitives have soft spatial influence; they do not directly provide a binary free-space label.',wall:'Gaussian footprints can represent its appearance, including where visible around the pole.'}[q];
    }
    document.querySelector('#reference-slice').innerHTML=slice(q);document.querySelector('#r-title').textContent=title;document.querySelector('#r-description').textContent=description;document.querySelector('#r-visual').innerHTML=visual;document.querySelector('#r-question').textContent=labels[q]+': what is available?';document.querySelector('#r-answer').textContent=answer;document.querySelector('#rinfo').textContent=note;
    document.querySelector('#r-legend').textContent=s.mode==='occupancy'?'Blue fill: inside the known pole. Orange: selected query.':'Schematic output for the same camera view.';
  }
  mode.onchange=draw;query.onchange=draw;draw();
}
function evaluation(){
  const stage=state.evaluation;
  const lesson=`<div class="workspace">${stageNav()}<div class="section-head"><div><p class="eyebrow">05 / EVALUATE DEPTH AND GEOMETRY</p><h2>What does a depth score tell us?</h2><p>Two comparisons use the same pole at 2 m and wall at 6 m. They ask different questions about a depth prediction.</p></div><aside class="note"><strong>LEARNING OBJECTIVE</strong>Explain the effect of scale alignment and why averages can hide local failures.<br><br>${slides.evaluation}</aside></div>
  <section class="eval-comparison" aria-labelledby="scale-heading"><p class="eyebrow">COMPARISON 1 / SCALE</p><h3 id="scale-heading">Is the scene the right size?</h3><p>The prediction has the right relative depths, but all distances are twice the reference. Change the multiplier and compare the original and adjusted prediction.</p><div class="eval-controls"><label class="control"><span>Multiplier applied to every predicted depth <output id="scale-value">1.00</output></span><input id="scale-slider" type="range" min="0.25" max="1.25" step="0.05" value="1" aria-label="Scale multiplier"></label><div class="actions"><button type="button" id="scale-fit">Fit scale using reference</button><button type="button" id="scale-reset" class="secondary">Reset to 1</button></div></div>
  <div class="eval-triplet"><div class="scene-card"><h4>Reference</h4>${poleImage(2,6)}<p>Pole: <strong>2 m</strong><br>Wall: <strong>6 m</strong></p></div><div class="scene-card"><h4>Before adjustment</h4>${poleImage(4,12)}<p>Pole: <strong>4 m</strong><br>Wall: <strong>12 m</strong></p></div><div class="scene-card"><h4>After adjustment</h4><div id="scale-image"></div><p id="scale-depths"></p></div></div>
  <p class="depth-key">All depth images use the same colour scale: dark at 2 m or nearer, light at 12 m or farther.</p><div class="eval-calculations"><div><strong>Before: metric error</strong><p>Pole error: 4 - 2 = 2 m<br>Wall error: 12 - 6 = 6 m</p><p>Whole-image MSE = [16 × 2² + 224 × 6²] / 240<br><b>33.867 m²</b></p></div><div><strong>After: error at the selected scale</strong><p id="scale-errors"></p><p id="scale-mse"></p></div></div><div class="explainer" id="scale-lesson"></div><p class="hint">The fitted multiplier minimises squared error against the reference. This evaluates relative depth after alignment; it does not recover metric scale without reference data.</p></section>
  <section class="eval-comparison" aria-labelledby="pole-heading"><p class="eyebrow">COMPARISON 2 / LOCAL ERROR</p><h3 id="pole-heading">Can an average hide a missing object?</h3><p>The wall is predicted correctly. Change the predicted depth at the pole pixels and compare the error on those pixels with the error averaged over the entire image.</p><div class="eval-controls"><label class="control"><span>Predicted depth at pole pixels <output id="pole-value">6.00 m</output></span><input id="pole-slider" type="range" min="2" max="6" step="0.25" value="6" aria-label="Predicted depth at pole pixels"></label><div class="actions"><button type="button" id="pole-missing">Miss the pole</button><button type="button" id="pole-correct" class="secondary">Predict correct depth</button></div></div>
  <div class="scene-grid eval-pair"><div class="scene-card"><h4>Reference</h4>${poleImage(2,6)}<p>Pole: <strong>2 m</strong><br>Wall: <strong>6 m</strong></p></div><div class="scene-card"><h4>Prediction</h4><div id="pole-image"></div><p id="pole-depths"></p></div></div><p class="depth-key">At 6 m the pole has the same predicted depth as the wall and disappears. The dashed outline marks its reference location.</p><div class="eval-calculations"><div><strong>1. Look only at the pole</strong><p id="pole-calc"></p></div><div><strong>2. Average over the whole image</strong><p id="whole-calc"></p></div></div><p class="hint">The known reference defines the pole region: 16 of 240 pixels. The other 224 pixels show the correctly predicted wall.</p><div class="explainer" id="pole-lesson"></div></section>
  <div class="experiment"><b>TRY THE EXPERIMENT</b><ol>${current.instructions.map(t=>`<li>${t}</li>`).join('')}</ol></div>${nextStage()}</div>`;
  workspace.innerHTML=lesson;
  const scale=document.querySelector('#scale-slider'),pole=document.querySelector('#pole-slider');
  function drawScale(){const k=Number(scale.value),p=4*k,w=12*k,pe=p-2,we=w-6,mse=(16*pe*pe+224*we*we)/240;
    document.querySelector('#scale-value').textContent=k.toFixed(2);document.querySelector('#scale-image').innerHTML=poleImage(p,w);document.querySelector('#scale-depths').innerHTML=`Pole: <strong>${p.toFixed(2)} m</strong><br>Wall: <strong>${w.toFixed(2)} m</strong>`;
    document.querySelector('#scale-errors').textContent=`Pole error: ${p.toFixed(2)} - 2 = ${pe.toFixed(2)} m; wall error: ${w.toFixed(2)} - 6 = ${we.toFixed(2)} m.`;
    document.querySelector('#scale-mse').innerHTML=`Whole-image MSE = [16 × (${pe.toFixed(2)})² + 224 × (${we.toFixed(2)})²] / 240<br><b>${mse.toFixed(3)} m²</b>`;
    document.querySelector('#scale-lesson').textContent=Math.abs(k-.5)<1e-8?'At multiplier 0.5 both depths match. The aligned error is zero, but the original metric prediction remains wrong.':'The original prediction remains visible. Fitting a multiplier of 0.5 makes both depths match this reference.';
  }
  function drawPole(){const z=Number(pole.value),error=z-2,local=error*error,all=16*local/240,missing=Math.abs(z-6)<1e-8;
    document.querySelector('#pole-value').textContent=z.toFixed(2)+' m';document.querySelector('#pole-image').innerHTML=poleImage(missing?null:z,6,'solid',missing);document.querySelector('#pole-depths').innerHTML=`At pole pixels: <strong>${z.toFixed(2)} m</strong><br>Wall: <strong>6 m</strong>`;
    document.querySelector('#pole-calc').innerHTML=`Depth error = ${z.toFixed(2)} - 2 = ${error.toFixed(2)} m<br>Pole-region MSE = (${error.toFixed(2)})² = <b>${local.toFixed(3)} m²</b>`;
    document.querySelector('#whole-calc').innerHTML=`Whole-image MSE = [16 × ${local.toFixed(3)} + 224 × 0] / 240<br>= <b>${all.toFixed(3)} m²</b>`;
    document.querySelector('#pole-lesson').textContent=missing?'The pole has vanished, yet only 16 of 240 pixels contribute error. The whole-image average is 1.067 m², while the pole-region MSE is 16 m².':local===0?'The predicted pole and wall depths both match the reference.':'The pole-region error is averaged with 224 correct wall pixels in the whole-image score.';
  }
  scale.oninput=drawScale;pole.oninput=drawPole;document.querySelector('#scale-fit').onclick=()=>{scale.value='0.5';drawScale()};document.querySelector('#scale-reset').onclick=()=>{scale.value='1';drawScale()};document.querySelector('#pole-missing').onclick=()=>{pole.value='6';drawPole()};document.querySelector('#pole-correct').onclick=()=>{pole.value='2';drawPole()};drawScale();drawPole();
}
const renderers={ambiguity,sfm,learning,representations,evaluation};
function render(){updateNav();renderers[current.id]();workspace.querySelectorAll("[data-stage]").forEach(b=>b.addEventListener("click",()=>selectStage(b.dataset.stage)));syncShared();renderQuestions()}
function restoreHash(){const oldStereo=location.hash==='#twoview';if(oldStereo)state.prior.second=true;const next=sections.find(s=>'#'+s.id===(oldStereo?'#learning':location.hash));if(next)current=next;render()}
window.addEventListener('hashchange',restoreHash);
restoreHash();
